from datetime import timedelta


def _is_workday(day, holidays):
    return day.weekday() < 5 and day not in holidays


def add_workdays(start, days, holidays=()):
    """Move by working days, rolling forward for a zero offset."""
    if isinstance(days, bool) or not isinstance(days, int):
        raise TypeError("days must be an int")
    holidays = frozenset(holidays or ())
    if days == 0 and _is_workday(start, holidays):
        return start

    step = timedelta(days=-1 if days < 0 else 1)
    remaining = abs(days) or 1
    current = start
    while remaining:
        current += step
        if _is_workday(current, holidays):
            remaining -= 1
    return current


def count_workdays(first, last, holidays=()):
    """Count working days inclusively, negating a reversed interval."""
    if first > last:
        return -count_workdays(last, first, holidays)
    weeks, extra = divmod((last - first).days + 1, 7)
    weekdays = weeks * 5 + sum(
        (first.weekday() + offset) % 7 < 5 for offset in range(extra)
    )
    return weekdays - sum(
        first <= day <= last and day.weekday() < 5 for day in set(holidays or ())
    )
